-- Itemized materials on a main task (category) itself — the same material D
-- lines a subtask carries (estimate_task_material_assignments), for a
-- standalone main task with no subtasks (e.g. FORMWORKS & SCAFFOLDINGS),
-- added with its own Add Material in the Material Breakdown.
--
-- category_material_estimate stays the stored total: the main task's own
-- direct line plus these lines (updateCategoryMaterialAssignments keeps it
-- in sync), so every total and weight already built on it picks them up.
--
-- id is generated by default (not always) so Gantt undo/redo can restore a
-- line under its original id — see 0037_gantt_undo_redo.sql.
--
-- Run this AFTER 0057_progress_entry_costs.sql.

create table if not exists public.estimate_category_material_assignments (
  id bigint generated by default as identity primary key,
  category_id bigint not null references public.estimate_categories (id) on delete cascade,
  material_name text not null,
  specification text,
  planned_quantity numeric not null default 0,
  unit text,
  unit_cost numeric not null default 0,
  -- Null: Amount is planned_quantity * unit_cost; set: typed directly
  -- (see 0043_amount_overrides.sql).
  amount numeric,
  created_at timestamptz not null default now()
);

create index if not exists idx_estimate_category_material_assignments_category_id
  on public.estimate_category_material_assignments (category_id);

alter table public.estimate_category_material_assignments enable row level security;

drop policy if exists "Admins can view category material assignments" on public.estimate_category_material_assignments;
create policy "Admins can view category material assignments" on public.estimate_category_material_assignments
  for select using (public.get_my_role() = 'admin');
drop policy if exists "Admins can create category material assignments" on public.estimate_category_material_assignments;
create policy "Admins can create category material assignments" on public.estimate_category_material_assignments
  for insert with check (public.get_my_role() = 'admin');
drop policy if exists "Admins can update category material assignments" on public.estimate_category_material_assignments;
create policy "Admins can update category material assignments" on public.estimate_category_material_assignments
  for update using (public.get_my_role() = 'admin');
drop policy if exists "Admins can delete category material assignments" on public.estimate_category_material_assignments;
create policy "Admins can delete category material assignments" on public.estimate_category_material_assignments
  for delete using (public.get_my_role() = 'admin');

-- Same foreman access a subtask's own material lines have
-- (0051_foreman_project_access.sql), one level up.
drop policy if exists "Foremen can view category material assignments" on public.estimate_category_material_assignments;
create policy "Foremen can view category material assignments" on public.estimate_category_material_assignments
  for select using (public.is_category_foreman(category_id));
drop policy if exists "Foremen can create category material assignments" on public.estimate_category_material_assignments;
create policy "Foremen can create category material assignments" on public.estimate_category_material_assignments
  for insert with check (public.is_category_foreman(category_id));
drop policy if exists "Foremen can update category material assignments" on public.estimate_category_material_assignments;
create policy "Foremen can update category material assignments" on public.estimate_category_material_assignments
  for update using (public.is_category_foreman(category_id))
  with check (public.is_category_foreman(category_id));
drop policy if exists "Foremen can delete category material assignments" on public.estimate_category_material_assignments;
create policy "Foremen can delete category material assignments" on public.estimate_category_material_assignments
  for delete using (public.is_category_foreman(category_id));
